CREATE TEMPORARY VIEW rec_realtime_user_bhv_wide_v1 AS SELECT t1.event_time,t1.event,t1.event_value,t1.item_id,t1.mmb_id,t1.request_id,t2.item_type,t2.cate_id_path,t2.related_goods_ids,t2.brand,t2.core_entity,t2.dianpufensi,t2.dianpupingfen,t2.discount_intensity,t2.first_cate_id,t2.second_cate_id,t2.third_cate_id,t2.pinpaidengji,t2.price_tag,t2.promotion_channel,t2.publish_user,t2.site,t2.spu_id,t2.username,HashBucket(t1.mmb_id,2) group_key FROM rec_realtime_user_bhv t1 LEFT JOIN home_flow_2604_ads_log_zhekou_rec_item_basic_info_preprocess_v1 FOR SYSTEM_TIME AS OF PROCTIME() t2 ON t1.item_id=t2.item_id
;

CREATE TEMPORARY VIEW rec_realtime_user_bhv_wide_delay_v1 AS SELECT delay_info[1] mmb_id,delay_info[2] item_id,delay_info[3] event,delay_info[4] cate_id_path,delay_info[5] related_goods_ids,delay_info[6] brand,delay_info[7] core_entity,delay_info[8] first_cate_id,delay_info[9] second_cate_id,delay_info[10] third_cate_id,delay_info[11] price_tag,delay_info[12] promotion_channel,delay_info[13] publish_user,delay_info[14] site,delay_info[15] spu_id,delay_info[16] discount_intensity,delay_info[17] dianpupingfen,delay_info[18] pinpaidengji,delay_info[19] dianpufensi,delay_info[20] item_type,delay_info[21] username,CAST(delay_info[22] AS BIGINT) event_time,CAST(delay_info[25] AS BIGINT) sys_time,CAST(delay_info[26] AS INT) delay_flag FROM (SELECT MessageDelay(ARRAY[mmb_id,item_id,event,cate_id_path,related_goods_ids,brand,core_entity,CAST(first_cate_id AS STRING),CAST(second_cate_id AS STRING),CAST(third_cate_id AS STRING),price_tag,promotion_channel,publish_user,site,spu_id,discount_intensity,dianpupingfen,pinpaidengji,dianpufensi,item_type,username],event_time,ARRAY[3600,10800,43200,86400],group_key,IF(event IN ('click','conversion','favorite'),true,false),ARRAY['']) delay_info FROM rec_realtime_user_bhv_wide_v1 GROUP BY group_key) sq0
;

